            ["hvci"]="VBS हाइपरवाइज़र में कर्नेल कोड अखंडता जाँच चलाता है, अहस्ताक्षरित/सुभेद्य ड्राइवर रोकता है। BYOVD हमले रोकता है। प्रभाव: ड्राइवर-भारी I/O पर 2-5%। केवल BSOD या एंटी-चीट विरोध होने पर अक्षम करें।",
            ["firewall"]="स्थितिपूर्ण पैकेट निरीक्षण और अनुप्रयोग-स्तरीय फ़िल्टरिंग। IPsec, WFP और VPN हेतु BFE आवश्यक। ओवरहेड: 0.1% से कम CPU। अक्षम करने से SMB, RDP पार्श्व गति हेतु उजागर होते हैं। हमेशा सक्षम रखें।",
            ["lua"]="न्यूनतम-विशेषाधिकार प्रवर्तन हेतु मानक और उन्नत टोकन संदर्भ अलग करता है। अक्षम करने से कोई भी प्रक्रिया सिस्टम निर्देशिकाओं में लिख सकती है। सक्षम रखें।",
            ["vulnerable-driver-blocklist"]="HVCI + CI से बूट पर ज्ञात-शोषित कर्नेल ड्राइवर रोकता है। BYOVD हमले लक्षित करता है। शून्य रनटाइम लागत। पुराने ड्राइवर आवश्यक न होने पर हमेशा सक्षम करें।",
            ["nx-mode"]="हार्डवेयर Data Execution Prevention (DEP) नियंत्रित करता है। OptIn (डिफ़ॉल्ट): केवल सिस्टम प्रक्रियाएँ। OptOut: सभी प्रक्रियाएँ। AlwaysOn: सबसे सुरक्षित पर पुराने ऐप टूट सकते हैं। नगण्य CPU ओवरहेड।",
            ["show-tray-icons"]="प्रति-उपयोगकर्ता एक्सप्लोरर सेटिंग। Windows 11 22H2+ पर अनदेखा, जहाँ प्रति-आइकन स्थिति NotifyIconSettings में गई। एक्सप्लोरर पुनरारंभ के बाद प्रभाव।",
            ["menus-delay"]="प्रति-उपयोगकर्ता स्ट्रिंग मान। तत्काल प्रभाव।",
            ["network-throttling"]="केवल MMCSS कार्य चलते समय लगता है। अक्षम करने से QoS आरक्षण भी शून्य होता है। उच्च-थ्रूपुट स्थानांतरण में मदद करता है, पिंग में नहीं।",
            ["error-reporting"]="WerSvc (फ़ैक्टरी मैन्युअल) और wercplsupport रोकता है। क्रैश रिपोर्ट Microsoft तक पहुँचना बंद। रीबूट आवश्यक।",
            ["compat-assistant"]="पृष्ठभूमि संगतता जाँच रोकता है। रीबूट आवश्यक।",
            ["sticky-keys"]="प्रति-उपयोगकर्ता और डिफ़ॉल्ट-उपयोगकर्ता हाइव। Shift x5 संकेत समाप्त करता है। रीबूट आवश्यक नहीं।",
            ["smb1"]="पदावनत और असुरक्षित (WannaCry)। प्राचीन NAS साझों हेतु आवश्यक न होने पर अक्षम रखें। रीबूट आवश्यक।",
            ["smb2"]="चेतावनी: अक्षम करने से आधुनिक फ़ाइल साझाकरण, प्रिंटर और डोमेन पहुँच टूटती है। केवल पृथक पुराने परीक्षण हेतु। रीबूट आवश्यक।",
            ["ntfs-timestamp"]="अक्षम करने से मामूली SSD लेखन बचता है। कोई स्थिति सूचक नहीं (जाँच असमर्थित)। तत्काल प्रभाव।",
            ["system-restore"]="चेतावनी: अक्षम करने से मौजूदा शैडो प्रतियाँ अपरिवर्तनीय हटती हैं। रीबूट आवश्यक।",
            ["superfetch"]="SSD पर Windows स्वतः अनुकूल होता है; अक्षम करने से ऐप लॉन्च धीमा हो सकता है। केवल SysMain गड़बड़ी पर बंद करें। रीबूट आवश्यक।",
            ["homegroup"]="Windows 10 1803 के बाद HomeGroup हटाया गया; अक्षम करना सुरक्षित है। रीबूट आवश्यक।",
            ["media-sharing"]="केवल DLNA स्ट्रीमिंग हेतु आवश्यक। सक्षम करने से ऑन-डिमांड मैन्युअल पुनर्स्थापित होता है। रीबूट आवश्यक।",
            ["regbackup"]="बंद होने पर Windows 10 1803+ बैकअप छोड़ता है। रीबूट आवश्यक नहीं।",
            ["compact-mode"]="प्रति-उपयोगकर्ता। एक्सप्लोरर विंडो पुनः खोलने पर प्रभाव।",
            ["long-paths"]="लाभ हेतु ऐप्स को longPathAware समर्थन घोषित करना चाहिए। सक्षम करना सुरक्षित है। रीबूट आवश्यक।",
            ["quickaccess-history"]="अक्षम करने से गोपनीयता निशान मिटता है पर सुविधाजनक शॉर्टकट हटते हैं। प्रति-उपयोगकर्ता।",
            ["insider-service"]="केवल Insider पूर्वावलोकन बिल्ड पर आवश्यक। रीबूट आवश्यक।",
            ["sensor-services"]="सक्षम करने से ऑन-डिमांड मैन्युअल पुनर्स्थापित होता है। अक्षम करने से टैबलेट पर स्वतः चमक और घुमाव टूटता है। रीबूट आवश्यक।",
            ["search-index"]="अक्षम करने से फ़ाइल खोज धीमी होती है पर डिस्क/CPU मंथन बचता है, और बंद रहते Start/Outlook खोज टूटती है। पुनः सक्षम करने से विलंबित प्रारंभ पुनर्स्थापित होता है। रीबूट आवश्यक।",
            ["telemetry-services"]="DiagTrack, diagnosticshub, dmwappushservice और WdiServiceHost रोकता है। फ़ीडबैक उपकरण शांत होते हैं। रीबूट आवश्यक।",
            ["modern-standby"]="अक्षम करने से S3 बाध्य होता है। पहले powercfg /a चलाएँ: केवल-S0 हार्डवेयर पर स्लीप गायब हो सकती है। Microsoft केवल पुनः स्थापना से बदलने का समर्थन करता है। रीबूट आवश्यक।",
            ["widgets-board"]="प्रति-उपयोगकर्ता। हाल के Windows 11 बिल्ड में पुनः दिख सकता है; मशीन-व्यापी नीति News and interests में है। तत्काल प्रभाव।",
            ["news-interests"]="EnableFeeds पुरानी Win10 कुंजी है, Win11 पर हानिरहित। रीबूट आवश्यक नहीं।",
            ["store-updates"]="नए प्रोफाइल पर Candy Crush-शैली स्वतः स्थापना रोकता है। Store स्वयं काम करता रहता है। रीबूट आवश्यक नहीं।",
            ["telemetry-tasks"]="CEIP, Compatibility Appraiser, Disk Diagnostics और फ़ीडबैक कार्य अक्षम करता है। समय-सिंक, SmartScreen, Store-update और File History कार्य जानबूझकर अछूते हैं। कोई स्थिति सूचक नहीं (जाँच असमर्थित)।",
            ["cortana"]="AllowCortana Windows 11 पर नो-ऑप है (Cortana 2023 में हटाई गई); वेब-खोज कुंजियाँ वहाँ भी काम करती हैं। स्थानीय फ़ाइल खोज काम करती रहती है।",
            ["startmenu-ads"]="प्रति-उपयोगकर्ता ContentDeliveryManager स्विच। तत्काल प्रभाव।",
            ["gamebar"]="अक्षम करने से पृष्ठभूमि-रिकॉर्डिंग ओवरहेड मुक्त होता है। प्रति-उपयोगकर्ता और एक मशीन नीति।",
            ["gamemode"]="HwSchMode 2 हार्डवेयर शेड्यूलिंग अनुरोध करता है (WDDM 2.7+); पुराने GPU पर बाध्य करने से TDR/BSOD हो सकता है। रीबूट अनुशंसित।",
            ["ink-workspace"]="मशीन नीतियाँ और प्रति-उपयोगकर्ता टच स्विच। रीबूट आवश्यक नहीं।",
            ["spelling-typing"]="प्रति-उपयोगकर्ता टच-कीबोर्ड कुंजियाँ (समुदाय-दस्तावेज़ित); हटाने से डिफ़ॉल्ट पुनर्स्थापित होते हैं। तत्काल प्रभाव।",
            ["cloud-clipboard"]="स्थानीय कॉपी-पेस्ट काम करता रहता है; केवल इतिहास और क्लाउड सिंक रुकता है।",
            ["cast-to-device"]="शेल-एक्सटेंशन ब्लॉक प्रविष्टि टॉगल करता है। तत्काल प्रभाव।",
            ["chrome-debloat"]="लाइव Chrome नीतियाँ सेट करता है (मेट्रिक्स, फ़ीडबैक, डोमेन विश्वसनीयता, पूर्वानुमान, सुझाव, पृष्ठभूमि मोड, GenAI)। अगले लॉन्च पर लागू; प्रबंधित दिखता है। पूर्णतः प्रतिवर्ती।",
            ["firefox-debloat"]="एंटरप्राइज़ नीतियाँ (टेलीमेट्री, अध्ययन, डिफ़ॉल्ट-ब्राउज़र एजेंट, सुझाव, FirefoxSuggest, क्रैश स्वतः भेजना) और नाम पैटर्न से Default Browser Agent कार्य अक्षम करना (इसका हैश बदलता है)। अगले लॉन्च पर लागू; प्रतिवर्ती। अपडेट कभी छुए नहीं जाते।",
            ["office-debloat"]="चार Office टेलीमेट्री एजेंट कार्य और दस्तावेज़ित OSM, फ़ीडबैक, गोपनीयता और FirstRun स्विच (HKCU) अक्षम करता है। Office बंद होना चाहिए। वर्तमान उपयोगकर्ता पर लागू; प्रतिवर्ती।",
            ["nvidia-telemetry"]="NvTelemetryContainer Start=4 सेट करता है (सेवा पंजीकृत रहते भी निष्क्रिय) और सात रूट NvTm* रिपोर्ट कार्य अक्षम करता है। NVIDIA ड्राइवर बिना निष्क्रिय; NvContainer/NvDisplay अछूते। प्रतिवर्ती।",
            ["vscode"]="HKCU\\Software\\Policies\\Microsoft\\VSCode लिखता है: TelemetryLevel बंद, EnableFeedback 0, UpdateMode manual, DictationLLMCleanup 0। अगले पुनरारंभ पर लागू। प्रतिवर्ती।",
            ["vs-telemetry"]="दस्तावेज़ित SQM ऑप्ट-आउट और पुरानी TurnOffSwitch (आंतरिक, पुराने संस्करणों हेतु रखी गई)। VSCommon 64-बिट दृश्य में 2015-2022 कवर करता है। संग्राहक सेवा अछूती छोड़ी गई है।",
        
            ["mitigations-off"]="Set-ProcessMitigation -System से Windows सिस्टम-व्यापी एंटी-एक्सप्लॉइट शमन बंद करता है। सक्षम करने से डिफ़ॉल्ट पुनर्स्थापित होते हैं। पूर्ण जोखिम पर मामूली लाभ (0-2% CPU)।",
            ["disable-pca"]="PCA दिखाता है यह प्रोग्राम सही से स्थापित नहीं हुआ होगा। DisablePCA=1 इसे मौन करता है। सजावटी, कोई प्रदर्शन प्रभाव नहीं।",
            ["spectre-meltdown-off"]="FeatureSettingsOverride=3 उन्हें अक्षम करता है, 0 पुनर्स्थापित करता है (मास्क 3)। रीबूट आवश्यक। आधुनिक CPU पर 1-3% लाभ, पुराने Intel पर अधिक।",
